from zipfile import ZipFile
from lxml import etree
p='/work/complaint_preparation.docx'
with ZipFile(p) as z:
 bad=[]
 for name in z.namelist():
  if name.endswith(('.xml','.rels')):
   try: etree.fromstring(z.read(name))
   except Exception as e: bad.append((name,str(e)))
 print('XML parts:',sum(x.endswith(('.xml','.rels')) for x in z.namelist()),'malformed:',bad)
 root=etree.fromstring(z.read('word/styles.xml'))
 ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
 for s in root.xpath('.//w:style[@w:styleId="Title" or @w:styleId="Heading1" or @w:styleId="Heading2" or @w:styleId="Heading3"]',namespaces=ns):
  name=s.find('w:name',namespaces=ns).get('{%s}val'%ns['w'])
  rf=s.find('w:rPr/w:rFonts',namespaces=ns)
  print('style',name, 'fonts', None if rf is None else [rf.get('{%s}%s'%(ns['w'],k)) for k in ('ascii','hAnsi','eastAsia','cs')])
